'use strict';
window.RepoAdminHelp=(()=>{
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const repo='https://github.com/sparx1981/RepoShelf';
function code(id,text){return `<div class="help-code"><button type="button" class="copy-code" data-copy-code="${id}">Copy</button><pre id="${id}"><code>${escape(text)}</code></pre></div>`}
function flag(ok){return `<span class="setup-flag ${ok?'ready':'missing'}">${ok?'Configured':'Needs setup'}</span>`}
function render(setup){const origin=setup.origin,remote=`[mcp_servers.reposhelf]\nurl = "${origin}/api/mcp"\nbearer_token_env_var = "REPOSHELF_API_KEY"`,desktop=JSON.stringify({mcpServers:{reposhelf:{command:'node',args:['/absolute/path/RepoShelf/scripts/mcp-server.mjs','--remote',origin],env:{REPOSHELF_API_KEY:'YOUR_PRIVATE_API_KEY'}}}},null,2);return `<section class="analytics-box help-status"><h3>Connection status</h3><div class="setup-status"><span>Supabase account configuration</span>${flag(setup.supabase.configured)}<span>Analytics ingestion key</span>${flag(setup.supabase.analyticsKeyConfigured)}<span>MCP / agent API key</span>${flag(setup.agentKeyConfigured)}</div><p class="analytics-caption">These flags confirm environment settings are present. They do not test credentials, OAuth or migrations. Secret values are never displayed.</p></section><div class="help-layout"><section class="analytics-box help-card help-wide"><p class="eyebrow">DISCOVERY &amp; RANKING</p><h3>How listings earn their place</h3><p>Each ribbon starts with eligible listings and your active filters. Its selection and ordering then follow these rules.</p><dl class="help-ranking"><div><dt>Popular</dt><dd>GitHub repositories use stars and forks, with 70% weight on stars and 30% on forks after logarithmic scaling. Hugging Face Spaces use likes. When sources are mixed, listings are compared by their popularity percentile within their own source in the candidate pool.</dd></div><div><dt>Trending</dt><dd>GitHub repositories with measured positive star or fork growth per day. The score uses the same 70/30 logarithmic weighting. A saved baseline must be 1–9 days old, preferably seven days, and the latest observation must be within two days. Listings without enough history do not qualify.</dd></div><div><dt>Editor’s picks</dt><dd>Administrator selections in their saved order by default. Edit the built-in row in <button class="help-inline-button" data-admin-tab="editorial">Storefront editor</button> to change the projects, order or selection mode. Every displayed pick must pass the featured checks below.</dd></div><div><dt>Hero · In the spotlight</dt><dd>Up to five eligible administrator selections, in saved order by default. Manage them in Storefront editor. Rotation changes the visible card; it does not change the ranking.</dd></div><div><dt>Category ribbons &amp; channels</dt><dd>Category ribbons default to Popular within their category; configured modes can change this. Technology channels match saved topics, dependencies and supported languages. Search and other active filters narrow the candidates.</dd></div><div><dt>New &amp; recent releases</dt><dd>Newest and recently updated use the source project’s creation or update date, rather than its import date. The hosted recent-release feed includes GitHub releases from the past 30 days and orders the latest release dates first.</dd></div><div><dt>Community discoveries</dt><dd>Hacker News points and comments, and Bluesky likes, replies and reposts, from the past 30 days. Signals are normalised within each community, weighted for recency and boosted by independent authors mentioning the same project.</dd></div><div><dt>Random &amp; daily order</dt><dd>Random order changes on each page load and stays stable while browsing. Daily order stays consistent for the row during the UTC day and changes at midnight UTC.</dd></div></dl><details class="help-reference"><summary>Featured eligibility and exact popularity formula</summary><p>Hero and Editor’s picks require an available, visible listing, a working demo check for its current demo URL within seven days, no temporary demo error, and a usable preview. A saved selection stays in the editor when it fails these checks and returns automatically when it qualifies again.</p><p><strong>GitHub Popular:</strong> <code>0.7 × ln(1 + stars) + 0.3 × ln(1 + forks)</code>. <strong>Spaces:</strong> <code>ln(1 + likes)</code>. Trending substitutes positive star and fork gains per day for lifetime totals.</p><p>Watching counts, RepoShelf likes, visits and demo clicks do not affect these scores. Sponsored placements are separate from editorial selections. A working demo or screenshot is not a security, licence or code-quality endorsement.</p></details></section><section class="analytics-box help-card help-wide"><p class="eyebrow">SYNC &amp; PUBLICATION</p><h3>Daily catalogue publication</h3><p>Repository checks repeat every 48 hours. Screenshot capture validates the demo in the same visit, before checking remaining due demos. Browser queues use their time budgets without fixed batch caps. Catalogue quality separates never-attempted work from three or more consecutive failures, with a 24-hour retry backoff. Existing successful demo checks and screenshots refresh after seven days; repository updates can also trigger screenshot refresh. Syncs save accumulated changes every two hours. The catalogue publishes daily at 06:35 UTC; use Publish now in Sync log for an earlier update. Code changes still deploy normally. Sync reports and growth history update without deploying.</p><p>For the in-app button and independent recovery, configure <code>REPOSHELF_ACTIONS_TOKEN</code>: a fine-grained GitHub token restricted to RepoShelf with Actions read/write. The existing submission workflow token is also supported. Configure a separate <code>REPOSHELF_SCHEDULER_KEY</code> with at least 32 random characters. Neither secret belongs in source code or URLs.</p><p>An external timer must POST to <code>/api/maintenance</code> every 30 minutes with an Authorization Bearer header containing the scheduler key. Enable failure alerts on that timer. Until it is configured, GitHub remains the only timer.</p><p><a href="https://github.com/sparx1981/RepoShelf/blob/main/docs/SCHEDULING.md" target="_blank" rel="noopener">Setup and recovery guide ↗</a></p></section><section class="analytics-box help-card help-wide"><p class="eyebrow">REMAINING LAUNCH WORK</p><h3>Before opening to everyone</h3><ul><li><strong>Dedicated support/privacy email:</strong> create a monitored mailbox, set <code>REPOSHELF_CONTACT_EMAIL</code> in Vercel and redeploy.</li><li><strong>Legal review:</strong> resolve the actual legal operator details and review the Terms and Privacy Policy before activation. A service name or email alone does not resolve this.</li><li><strong>Catalogue review:</strong> inspect <a href="/admin.html?tab=quality">Catalogue quality</a> and manually review featured images and descriptions. Coverage targets are 95% fresh repository checks, 95% demo validation and 90% screenshots.</li><li><strong>Launch testing:</strong> confirm the Android and iPhone journeys on physical devices and run a small beta before broader launch.</li></ul><p><a href="${repo}/blob/main/docs/PUBLIC_LAUNCH.md" target="_blank" rel="noopener">Device checklist and beta plan ↗</a> · <a href="/terms.html">Terms</a> · <a href="/privacy.html">Privacy Policy</a></p><p class="small">Completed migration and account setup tasks have been removed. The operational health monitor runs automatically; review alerts in Sync log. Real payments remain disabled.</p></section><section class="analytics-box help-card"><p class="eyebrow">CODING AGENTS</p><h3>Connect Codex to RepoShelf</h3><ol><li>Add <code>REPOSHELF_API_KEY</code> in Vercel’s Production environment and redeploy. Use at least 32 random characters.</li><li>Set the same key securely in the environment running Codex.</li><li>Add this to your Codex MCP configuration:</li></ol>${code('codex-mcp-config',remote)}<p class="small">Ask your agent to search RepoShelf before building, inspect project context, then read saved READMEs and licences. All tools are read-only.</p><p><a href="${repo}/blob/main/docs/AGENT_API.md" target="_blank" rel="noopener">Full API and MCP guide ↗</a></p></section><section class="analytics-box help-card"><p class="eyebrow">CODING AGENTS</p><h3>Connect Claude Desktop</h3><ol><li>Clone RepoShelf and run <code>npm install</code>. Node.js 20 or later is required.</li><li>Use the local stdio bridge below to read the current hosted catalog.</li><li>Replace the example path and key in your private Claude Desktop configuration, then restart the client.</li></ol>${code('claude-mcp-config',desktop)}<p class="small">The key above is a placeholder. Keep your actual key private and out of Git, URLs and command-line arguments. A client secret manager/environment configuration is preferable when available.</p><details><summary>Use a local checkout without a hosted key</summary><p>Remove <code>--remote</code>, the hosted URL and the <code>env</code> entry. The server then reads the saved catalog in your checkout. Use <code>git pull</code> to keep it current.</p></details><p class="small">The remote MCP endpoint uses a Bearer header. OAuth-only connectors need the stdio bridge or a client that supports custom authentication.</p></section><section class="analytics-box help-card"><p class="eyebrow">ADMINISTRATION</p><h3>Give someone administrator access</h3><ol><li>Ask the person to sign in to RepoShelf with GitHub once.</li><li>Open <button class="help-inline-button" data-admin-tab="users">Users & roles</button> and search their GitHub username, GitHub ID or account UUID.</li><li>Check the identity, select <strong>Grant admin</strong>, and confirm. The person can reload to see the admin menu.</li></ol><p class="small">Administrators can manage category rows, read analytics and grant roles. User-controlled profile metadata never grants access. Your own role and the last administrator are protected, and changes are recorded.</p></section><section class="analytics-box help-card"><p class="eyebrow">ACCOUNT &amp; SUBMISSIONS</p><h3>Existing account features</h3><p><a href="/account.html">Account &amp; data</a> lets users export their data and request deletion. Deletion requires a recent GitHub sign-in and protects the last administrator and accounts with reserved or running promotions.</p><p>Likes, verified public forks, viewing history and hide-seen settings sync across signed-in devices. Viewing history is private and separate from analytics.</p><p><a href="/submissions.html">Submit repository</a> queues a public repository for validation. Submission scans are scheduled every 15 minutes. Requests and scan history are private; only public project details enter the catalogue.</p><details class="help-reference"><summary>Submission configuration reference</summary><p>The private <code>REPOSHELF_SUBMISSION_SYNC_KEY</code> must match in Vercel Production and GitHub Actions secrets and contain at least 32 random characters.</p><p><a href="${repo}/blob/main/docs/SUBMISSIONS.md" target="_blank" rel="noopener">Submission guide ↗</a></p></details></section><section class="analytics-box help-card"><p class="eyebrow">ACCOUNTS AND STORAGE</p><h3>Configure Supabase</h3><details class="help-reference"><summary>Connection settings and database reference</summary><ol><li>Connect a Supabase project to RepoShelf in Vercel’s Storage settings.</li><li>Apply the database migrations in order. Existing projects should apply only migrations they have not run yet.</li><li>Set the server variables below in Vercel’s Production environment, then redeploy.</li></ol><div class="help-table-wrap"><table class="analytics-table"><thead><tr><th>Setting</th><th>Purpose</th></tr></thead><tbody><tr><td><code>SUPABASE_URL</code></td><td>Project URL</td></tr><tr><td><code>SUPABASE_ANON_KEY</code></td><td>Publishable or legacy anon key</td></tr><tr><td><code>SUPABASE_SERVICE_ROLE_KEY</code></td><td>Private analytics ingestion</td></tr><tr><td><code>REPOSHELF_PUBLIC_URL</code></td><td>${escape(origin)}</td></tr></tbody></table></div><p class="small">Marketplace aliases are supported. Database and OAuth secrets stay on the server.</p><p><a href="${repo}/tree/main/supabase/migrations" target="_blank" rel="noopener">Migration files ↗</a> · <a href="${repo}/blob/main/docs/ACCOUNTS_AND_ADMIN.md" target="_blank" rel="noopener">Accounts and administration guide ↗</a></p><p><a href="https://supabase.com/dashboard" target="_blank" rel="noopener">Open Supabase dashboard ↗</a></p></details></section><section class="analytics-box help-card"><p class="eyebrow">GITHUB SIGN-IN</p><h3>GitHub sign-in</h3><details class="help-reference"><summary>OAuth and redirect configuration</summary><ol><li>Create a GitHub OAuth App. Its homepage is <code>${escape(origin)}</code>, and its callback is <code>https://YOUR_PROJECT.supabase.co/auth/v1/callback</code>.</li><li>Enable GitHub in Supabase Authentication → Providers and enter the OAuth app’s client ID and secret.</li><li>Set Supabase’s Site URL to <code>${escape(origin)}</code> and allow this redirect:</li></ol>${code('oauth-redirect-url',origin+'/api/auth?action=callback')}<p class="small">Custom and preview domains need their own explicit settings. Repository write access is not needed for sign-in or browsing; fork links open GitHub.</p><p><a href="${repo}/blob/main/docs/ACCOUNTS_AND_ADMIN.md" target="_blank" rel="noopener">Complete accounts and administration guide ↗</a></p></details></section><section class="analytics-box help-card"><p class="eyebrow">SPONSORED · OPTIONAL TEST PROGRAMME</p><h3>Promotion reference</h3><p>£15 for 30 active days, five slots and administrator approval. Placements use a separate Sponsored ribbon; test placements are visible only to administrators.</p><details class="help-reference"><summary>Stripe test configuration</summary><p>Configure Stripe test credentials, a signed webhook and matching promotion sync keys in Vercel and GitHub Actions. Live keys are rejected; real payments remain disabled.</p><p><a href="${repo}/blob/main/docs/PROMOTIONS.md" target="_blank" rel="noopener">Promotion setup guide ↗</a> · <a href="/promotions.html?manage=1">Manage promotions ↗</a></p></details></section><section class="analytics-box help-card help-wide"><p class="eyebrow">TROUBLESHOOTING</p><h3>When something needs attention</h3><ul><li><strong>Sync succeeded without changes:</strong> open <a href="/admin.html?tab=sync">Sync log</a> and inspect coverage, stage results and debugging details. Look for work deferred to the next browser batch, capture failures or discovery paused by coverage targets. Saved catalogue changes and a successful live deployment are separate checks.</li><li><strong>Live site is behind:</strong> check the deployment status in Sync log. Vercel rate limits can block publication even when catalogue processing succeeds.</li><li><strong>MCP 503 or 401:</strong> check that the server key is configured, the client key matches and the environment changes have been deployed.</li><li><strong>Sign-in redirects incorrectly:</strong> check GitHub’s Supabase callback, Supabase’s Site URL and the RepoShelf redirect allowlist in the configuration reference.</li><li><strong>A user is missing:</strong> they must complete GitHub sign-in once. Clear the search or check their account ID in Users &amp; roles.</li><li><strong>Analytics appear unchanged:</strong> administrator activity and browser privacy opt-outs are excluded. Check the selected date range and refresh, then check the ingestion configuration if ordinary visitor activity is missing.</li></ul><p class="small">Catalogue processing and browser batches are scheduled every two hours; the health monitor checks every 30 minutes. GitHub can delay scheduled triggers. Discovery pauses while catalogue quality is below target. Fork clicks show intent; verified public forks confirm the result.</p></section></div>`}
document.addEventListener('click',async event=>{const button=event.target.closest('[data-copy-code]');if(!button)return;const text=document.getElementById(button.dataset.copyCode)?.textContent;if(!text)return;try{await navigator.clipboard.writeText(text);button.textContent='Copied';setTimeout(()=>button.textContent='Copy',1500)}catch{button.textContent='Select text to copy'}});
return {render};
})();
